//! The check [`Implementation::detect`](crate::Implementation::detect) and
//! [`init`](crate::init) run on a selection before using it. Core has no X11 self-test; the
//! digests come from Core's own code (`vectors.rs`, generated by
//! `contrib/self-test-vectors.py`).
//!
//! It hashes, with the selection under test:
//! - X11 of the mainnet genesis header (BLAKE's 80-byte path), the empty input, 120 bytes of
//!   0xff (BLAKE's two final blocks) and the 300 bytes `i as u8` (two full blocks and a tail);
//! - every chain function of 64 bytes of 0x00 and of 64 bytes of 0xff, the carry and saturation
//!   extremes, so each vector function the selection uses runs on inputs of its own.
//!
//! That is 4 X11 hashes and 22 single functions, about 2.2 X11 hashes' worth of work besides:
//! roughly 0.25M instructions with every backend and 0.9M with the portable code (well under a
//! millisecond), paid once per selection tried.

mod vectors;

use crate::{Implementation, Stage};

/// The mainnet genesis header (Core: `chainparams.cpp`, `CreateGenesisBlock`).
const GENESIS: [u8; 80] = [
    0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0xc7, 0x62, 0xa6, 0x56, 0x7f, 0x3c, 0xc0, 0x92, 0xf0, 0x68, 0x4b, 0xb6,
    0x2b, 0x7e, 0x00, 0xa8, 0x48, 0x90, 0xb9, 0x90, 0xf0, 0x7c, 0xc7, 0x1a, 0x6b, 0xb5, 0x8d, 0x64,
    0xb9, 0x8e, 0x02, 0xe0, 0x02, 0x2d, 0xdb, 0x52, 0xf0, 0xff, 0x0f, 0x1e, 0xc2, 0x3f, 0xb9, 0x01,
];

/// The 300-byte input: 0, 1, .., 255, 0, .., 43.
const RAMP: [u8; 300] = {
    let mut ret = [0u8; 300];
    let mut i = 0;
    while i < 300 {
        ret[i] = i as u8;
        i += 1;
    }
    ret
};

const _: () = assert!(vectors::STAGES.len() == Stage::ALL.len());

/// Whether `imp` gives Core's digests for every self-test input.
pub(crate) fn passes(imp: &Implementation) -> bool {
    // Sized by the generated digests, so a changed vector count fails to compile.
    let x11_inputs: [&[u8]; vectors::X11.len()] = [&GENESIS, &[], &[0xff; 120], &RAMP];
    x11_inputs.iter().zip(&vectors::X11).all(|(input, want)| imp.x11(input) == *want)
        && Stage::ALL.iter().zip(&vectors::STAGES).all(|(&stage, [zeros, ones])| {
            imp.stage(stage, &[0x00; 64]) == *zeros && imp.stage(stage, &[0xff; 64]) == *ones
        })
}

#[cfg(test)]
mod tests {
    /// The first X11 vector is Core's `hashGenesisBlock` for mainnet.
    #[test]
    fn genesis_is_core_hash_genesis_block() {
        let mut h = super::vectors::X11[0];
        h.reverse();
        let hex: [u8; 32] = h;
        assert_eq!(
            hex,
            [
                0x00, 0x00, 0x0f, 0xfd, 0x59, 0x0b, 0x14, 0x85, 0xb3, 0xca, 0xad, 0xc1, 0x9b, 0x22,
                0xe6, 0x37, 0x9c, 0x73, 0x33, 0x55, 0x10, 0x8f, 0x10, 0x7a, 0x43, 0x04, 0x58, 0xcd,
                0xf3, 0x40, 0x7a, 0xb6
            ]
        );
    }
}
